<!--vbase-->
<template>
  <f-btn
    id="btn_upload_invoice"
    data-test="upload-document-btn"
    class="mt-20"
    v-if="isDashboard"
    @click="
      multiUploaderDialog = true;
      uploadedFiles = [];
    "
    :label="$t('upload')"
  >
    <Icon icon="mdi:upload" width="20" height="20" />
    <q-tooltip>
      <div v-html="$t('import_files_info')"></div>
    </q-tooltip>
  </f-btn>

  <q-btn
    class="validation-view-button font-size-15 icon-grey"
    id="btn_merge"
    flat
    @click="multiUploaderDialog = true"
    v-else
  >
    <Icon icon="mdi:call-merge" width="20" height="20" />
    <q-tooltip>{{ $t('merge') }}</q-tooltip>
  </q-btn>

  <!-- MultiUploader DIALOG STARTS -->

  <q-dialog v-model="multiUploaderDialog" data-test="document-upload-dialog">
    <q-card style="width: 50vw">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span data-test="upload-dialog-title">
            {{ $t('heading1') }}
          </span>
        </q-toolbar-title>
        <f-btn
          flat
          round
          dense
          icon="close"
          v-close-popup
          @click="closeDialog"
          data-test="close-upload-dialog-btn"
        />
      </q-toolbar>

      <q-card-section>
        <div
          class="drag-area text-center full-width"
          id="box-droppable"
          @drop="drop"
          @dragover="allowDrop"
          @dragleave="dragLeave"
          @click="triggerFileInput"
          data-test="upload-drag-area"
        >
          <div class="upload-icon-wrapper">
            <q-icon name="upload" class="upload-icon-img" />
          </div>
          <div class="upload-text">
            {{ $t('land_dragndrop') }} {{ $t('land_or') }}
            <span class="upload-link">{{ $t('click_to_upload') }}</span>
          </div>
          <q-file
            ref="fileInput"
            style="display: none"
            data-test="document-upload-input"
            multiple
            @update:model-value="uploadFile"
            v-model="uploadedFiles"
          >
          </q-file>
        </div>
        <div class="q-mt-md">
          <div class="row items-center no-wrap classify-controls">
            <f-toggle size="xs"
              v-model="classifyAsEnabled"
              color="primary"
              keep-color
              label="Classify as"
            />
            <q-select
              class="q-ml-md classify-select"
              data-test="upload-doctype-select"
              dense
              outlined
              emit-value
              map-options
              use-input
              clear-icon="close"
              :input-debounce="200"
              :disable="!classifyAsEnabled || !active_doc_type_list.length"
              :options="filteredDocTypes"
              option-label="label"
              option-value="value"
              :placeholder="$t('doc_type')"
              v-model="upload_classify_doctype"
              @filter="filterDocTypes"
            >
              <template #option="{ opt, itemProps }">
                <q-item v-bind="itemProps" dense>
                  <q-item-section avatar>
                    <q-icon name="description" class="uploaded-file-icon" />
                  </q-item-section>
                  <q-item-section class="doc-type-option">
                    <span class="text-body2 doc-type-label">{{
                      opt.label
                    }}</span>
                  </q-item-section>
                </q-item>
              </template>
              <template #selected-item="{ opt }">
                <div class="row items-center no-wrap doc-type-selected">
                  <q-icon
                    name="description"
                    size="16px"
                    class="q-mr-sm uploaded-file-icon"
                  />
                  <span class="doc-type-label">{{ opt?.label }}</span>
                </div>
              </template>
            </q-select>
          </div>
          <template v-if="uploadedFiles && uploadedFiles.length">
            <q-separator class="uploaded-file-separator" />
            <q-list bordered separator dense class="q-mt-md uploaded-file-list">
              <q-item
                v-for="(file, index) in uploadedFiles"
                :key="`${file.name}-${file.lastModified}-${index}`"
                dense
                class="uploaded-file-item"
              >
                <q-item-section avatar>
                  <q-icon name="description" class="uploaded-file-icon" />
                </q-item-section>
                <q-item-section class="file-name text-body2">
                  {{ file.name }}
                </q-item-section>
                <q-item-section side>
                  <q-btn
                    flat
                    round
                    dense
                    icon="delete"
                    @click="removeUploadedFile(index)"
                  />
                </q-item-section>
              </q-item>
            </q-list>
          </template>
          <div class="row justify-end q-gutter-sm q-mt-lg">
            <f-btn
              appearance="cancel"
              :label="$t('cancel')"
              @click="handleCancel"
              data-test="upload-cancel-btn"
              style="flex: 1; width: 50%"
            />
            <f-btn
              :label="$t('upload')"
              color="primary"
              :disable="
                !uploadedFiles ||
                !uploadedFiles.length ||
                (classifyAsEnabled && !upload_classify_doctype) ||
                processing
              "
              :loading="processing"
              @click="handleUploadClick"
              data-test="upload-confirm-btn"
              style="flex: 1; width: 50%"
            />
          </div>
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>
  <!-- MultiUploader DIALOG END -->

  <q-dialog v-model="confirmMergeDialog" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('append_files_to_document') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          :label="$t('done')"
          v-close-popup
          @click="uploadFilesForValidation()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="selectOrg">
    <q-card class="width-500">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold">{{
            $t('select_sub_organizations_to_upload')
          }}</span>
        </q-toolbar-title>
      </q-toolbar>

      <q-card-section class="row items-center">
        <q-select
          clearable
          use-input
          emit-value
          map-options
          outlined
          dense
          option-value="id"
          option-label="name"
          v-model="selectedSubOrgId"
          :options="filteredSubOrgs"
          @filter="searchSubOrgs"
          :label="$t('sub_organizations')"
          class="full-width"
        />
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn :label="$t('done')" @click="processFiles(uploadedFiles)" />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { storeToRefs } from 'pinia';
import { dynamicObj } from './assets';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions/index';
import { documentListApiService } from 'src/services';
import { filters_reset_after_upload_setting } from 'src/constants';
import { isAllowedFileType } from 'src/utils/fileType';
import { filterStoreDocTypes } from 'src/utils/docTypeFilter';
import {
  useDashboardStore,
  useSettingStore,
  useDocumentStore,
  useDropdownStore,
  useUserStore,
} from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    isDashboard: {
      type: Boolean,
      default: true,
    },
    docId: {
      type: String,
      default: '',
    },
  },
  emits: ['setImages'],
  
  data() {
    return {
      filters_reset_after_upload_setting,
      confirmMergeDialog: ref(false),
    };
  },

  mounted() {
    // DPT-252: the eager getSubOrgsList() warm was removed from here. This
    // component's own sub-org dialog reads userStore.organizations (see
    // searchSubOrgs / checkOrgSelection), NOT the dropdown store's subOrgList.
    // The 11KB warm only fed the sub_org_name quick-search autocomplete, which
    // now self-loads lazily in useFieldValueSource.
    const docTypeResult: any = this.getDocTypesSubTypes();
    if (docTypeResult && typeof docTypeResult.then === 'function') {
      docTypeResult.then(() => this.resetDocTypeOptions());
    } else {
      this.resetDocTypeOptions();
    }
    document.removeEventListener('upload_files', this.uploadFilesEventHandler);
    document.addEventListener('upload_files', this.uploadFilesEventHandler);
  },
  unmounted: function () {
    document.removeEventListener('upload_files', this.uploadFilesEventHandler);
  },

  methods: {
    triggerFileInput() {
      const fileInput = this.$refs.fileInput as any;
      if (fileInput && fileInput.$el) {
        const input = fileInput.$el.querySelector('input[type="file"]');
        if (input) {
          input.click();
        }
      }
    },
    resetDocTypeOptions(source?: any[]) {
      if (!Array.isArray(this.filteredDocTypes)) {
        return;
      }
      this.filteredDocTypes.length = 0;
      const list = Array.isArray(source) ? source : this.active_doc_type_list;
      const filtered = filterStoreDocTypes(list, { excludeAll: true });
      for (const option of filtered) {
        this.filteredDocTypes.push(option);
      }
      if (this.upload_classify_doctype === 'all') {
        this.upload_classify_doctype = '';
        this.classifyAsEnabled = false;
      }
    },
    uploadFile(value: any) {
      this.uploadFiles(value);
    },

    allowDrop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.add('bg-grey-5');
      event.currentTarget.classList.add('bd-shadow');
    },

    drop(event: any) {
      event.preventDefault(); // will prevent file from opening in browser if dropped on exact location
      event.currentTarget.classList.remove('bg-grey-5');
      event.currentTarget.classList.remove('bd-shadow');

      this.uploadFiles(event.dataTransfer.files);
    },

    dragLeave(event: any) {
      event.currentTarget.classList.remove('bg-grey-5');
      event.currentTarget.classList.remove('bd-shadow');
    },

    uploadFilesEventHandler(e: any) {
      if (!e || !e.detail.files) {
        return;
      }
      this.resetDocTypeOptions();
      this.uploadFiles(e.detail.files);
    },

    // will handle file drop case and file select case
    uploadFiles(files: any) {
      if (!files || !files.length) {
        if (!this.uploadedFiles || !this.uploadedFiles.length) {
          notify.error(this.$t('NO_FILE_SELECTED'));
        }
        return;
      }
      for (const file of files) {
        if (!file) {
          continue;
        }
        const duplicate = this.uploadedFiles.some(
          (existing: any) =>
            existing.name === file.name &&
            existing.size === file.size &&
            existing.lastModified === file.lastModified,
        );
        if (!duplicate) {
          this.uploadedFiles.push(file);
        }
      }
      this.resetDocTypeOptions();
      this.selectedSubOrgId = '';
      this.selectOrg = false;
      if (Array.isArray(this.filteredSubOrgs)) {
        this.filteredSubOrgs.length = 0;
      }

      if ( !this.multiUploaderDialog ) {
        if (this.checkOrgSelection()) {
          return;
        }
        this.processFiles(files);
      }
    },
    handleUploadClick() {
      const files = this.uploadedFiles;
      if (!files.length) {
        notify.error(this.$t('NO_FILE_SELECTED'));
        return;
      }
      this.selectedSubOrgId = '';

      if (this.checkOrgSelection()) {
        this.multiUploaderDialog = false;
        return;
      }

      this.processFiles(files);
    },
    handleCancel() {
      this.closeDialog();
      this.resetUploaderState();
    },
    removeUploadedFile(index: number) {
      if (!this.uploadedFiles || !this.uploadedFiles.length) {
        return;
      }
      this.uploadedFiles.splice(index, 1);
      if (!this.uploadedFiles.length) {
        this.classifyAsEnabled = false;
        this.upload_classify_doctype = '';
      }
      this.resetDocTypeOptions();
    },
    resetUploaderState() {
      this.uploadedFiles.length = 0;
      this.classifyAsEnabled = false;
      this.upload_classify_doctype = '';
      this.selectOrg = false;
      this.selectedSubOrgId = '';
      this.filteredSubOrgs.length = 0;
      this.resetDocTypeOptions();
    },
    async processFiles(files: any) {
      if (!this.selectedSubOrgId && this.selectOrg) {
        notify.error(this.$t('SUBORG_MISSING'));
        return;
      }
      if (!files || !files.length) {
        notify.error(this.$t('NO_FILE_SELECTED'));
        return;
      }

      if (files.length > 10) {
        notify.error(this.$t('MAX_DOC_UPLOAD_LIMIT'));
        return;
      }
      try {
        this.processing = true;

        this.formData = new FormData();
        let invalidFileCounter = 0;

        if (this.upload_classify_doctype) {
          this.formData.append('doc_type', this.upload_classify_doctype);
        }
        for (const file of files) {
          if (this.hasAllowedFileType(file)) {
            this.formData.append('files', file);
          } else {
            invalidFileCounter++;
          }
        }

        if (invalidFileCounter > 0) {
          notify.error(this.$t('INVALID_FILES'));
          return;
        }

        this.multiUploaderDialog = false;

        if (this.isDashboard) {
          this.selectOrg = false;
          const effectiveSubOrgId = this.selectedSubOrgId || this.sub_org_id || '';
          await this.uploadFilesForDashBoard( this.formData, effectiveSubOrgId );
        } else {
          this.formData.append('doc_id', this.docId);
          this.confirmMergeDialog = true;
        }
      } catch (err: any) {
        logError(err);
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      } finally {
        this.processing = false;
        this.resetUploaderState();
      }
    },

    hasAllowedFileType(file: any) {
      return isAllowedFileType(file);
    },

    async uploadFilesForDashBoard(
      formData: FormData,
      selectedSubOrgId: string,
    ) {
      notify.info(this.$t('upload_in_progress'));
      const invoice_response = await documentListApiService.uploadFiles( formData, selectedSubOrgId,);

      if (Array.isArray(invoice_response)) {
        const errorMessages = invoice_response
          .filter((item: any) => item.success === false && item.message)
          .map((item: any) => item.message);

        const allFailed = errorMessages.length === invoice_response.length;

        if (errorMessages.length > 0) {
           notify.error(errorMessages.join('\n'));
        }

        if (allFailed) {
          return;
        }
      } else if (invoice_response.success === false) {
        throw { message: invoice_response.message || this.$t('DOC_UPLOAD_ERROR') };
      }

      setTimeout(() => {
        this.refreshDashboard();
      }, 1000);
    },

    async uploadFilesForValidation() {
      try {
        this.showLoading();
        const invoice_response =
          await documentListApiService.uploadFilesForValidation(this.formData);

        if (invoice_response.success === false) {
          logError(invoice_response);
          notify.error(this.$t('DOC_UPLOAD_ERROR'));
          notify.error(invoice_response.message);
          return;
        }

        await this.setDataToStoreAndStorage(invoice_response.data);

        if (!this.isDashboard) {
          notify.success(this.$t('operation_sucessfull'));
          setTimeout(() => {
            window.location.reload();
          }, 0);
        }
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
        this.processing = false;
      }
    },

    refreshDashboard() {
      const filter_setting =
        this.user_settings[this.filters_reset_after_upload_setting];
      if (filter_setting) {
        notify.info(
          this.$t('dashboard_filters_are_reset_automatically'),
        );
        const event = new CustomEvent('reset_filters', {});
        document.dispatchEvent(event);
        return;
      }
      const event = new CustomEvent('dashboard_refresh_data', {});
      document.dispatchEvent(event);
    },

    closeDialog() {
      this.multiUploaderDialog = false;
      this.resetUploaderState();
    },

    searchSubOrgs(val: string, update: any) {
      if (val === '') {
        update(() => {
          if (Array.isArray(this.filteredSubOrgs)) {
            this.filteredSubOrgs.length = 0;
            const list = this.organizations[0]?.sub_organisations || [];
            if (Array.isArray(list)) {
              this.filteredSubOrgs.push(...list);
            }
          }
        });
        return;
      }
      update(() => {
        const needle = val.toLowerCase();
        if (Array.isArray(this.filteredSubOrgs)) {
          this.filteredSubOrgs.length = 0;
          const list = this.organizations[0]?.sub_organisations || [];
          if (Array.isArray(list)) {
            for (const subOrg of list) {
              if (
                subOrg.name &&
                subOrg.name.toLowerCase().indexOf(needle) > -1
              ) {
                this.filteredSubOrgs.push(subOrg);
              }
            }
          }
        }
      });
    },
    filterDocTypes(val: string, update: any) {
      const options = this.active_doc_type_list || [];
      if (!val) {
        update(() => {
          this.resetDocTypeOptions();
        });
        return;
      }
      const needle = val.toLowerCase();
      update(() => {
        this.filteredDocTypes.length = 0;
        const filtered = filterStoreDocTypes(options, { excludeAll: true });
        for (const option of filtered) {
          const label = (option as any).label || (option as any).name || (option as any).value;
          if (label && label.toString().toLowerCase().includes(needle)) {
            this.filteredDocTypes.push(option);
          }
        }
      });
    },

    checkOrgSelection() {
      // Check if CROSS org is selected and has sub-organizations
      if (this.organizations[0]?.id === this.sub_org_id && this.organizations[0]?.sub_organisations?.length > 0) {
        const subOrgOptions = this.organizations[0].sub_organisations || [];
        if (Array.isArray(this.filteredSubOrgs)) {
          this.filteredSubOrgs.length = 0;
          if (Array.isArray(subOrgOptions)) {
            this.filteredSubOrgs.push(...subOrgOptions);
          }
        }
        this.selectOrg = true;
        this.resetDocTypeOptions();
        return true;
      }
      return false;
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const { processing, upload_classify_doctype } =
      storeToRefs(dashboard_store);

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    const doc_store = useDocumentStore();
    const { setDataToStoreAndStorage } = doc_store;

    const dropdown_store = useDropdownStore();
    // DPT-252: getSubOrgsList / subOrgList no longer used here (eager warm
    // removed; the sub-org dialog uses userStore.organizations instead).
    const { getDocTypesSubTypes } = dropdown_store;
    const { active_doc_type_list } = storeToRefs(dropdown_store);

    const user_store = useUserStore();
    const { organizations, sub_org_id } = storeToRefs(user_store);

    const multiUploaderDialog = ref(false);
    const uploadedFiles = ref([] as File[]);
    const classifyAsEnabled = ref(false);
    const filteredSubOrgs = ref([] as any);
    const selectedSubOrgId = ref('');
    const selectOrg = ref(false);
    const filteredDocTypes = ref(
      filterStoreDocTypes(active_doc_type_list.value, { excludeAll: true }),
    );

    return {
      sub_org_id,
      active_doc_type_list,
      processing,
      user_settings,
      organizations,
      getDocTypesSubTypes,
      setDataToStoreAndStorage,
      upload_classify_doctype,
      multiUploaderDialog,
      classifyAsEnabled,
      filteredSubOrgs,
      uploadedFiles,
      selectedSubOrgId,
      selectOrg,
      filteredDocTypes,
      formData: {} as FormData,
    };
  },
});
</script>

