import { allowed_file_types, allowed_file_extensions } from 'src/constants';

/** Lowercased file extension (without the dot), or '' if there is none. */
export function getFileExtension(name: string | null | undefined): string {
  const lower = (name || '').toLowerCase();
  const dot = lower.lastIndexOf('.');
  return dot >= 0 ? lower.slice(dot + 1) : '';
}

/**
 * Whether a file is an allowed upload type.
 *
 * Matches by MIME type when the browser supplies one, and falls back to the
 * file extension otherwise.
 *
 * Why the fallback matters: browsers leave `File.type` empty (or set a generic
 * `application/octet-stream`) for drag-and-drop from some sources, so a valid
 * `.pdf` can arrive without its real MIME type and must still be accepted. The
 * previous logic compared the bare extension ("pdf") against the MIME-type list
 * ("application/pdf"), which never matched and wrongly rejected such files —
 * surfacing the "Only PDF files can be uploaded" error for genuine PDFs.
 *
 * Deliberately permissive: a file whose extension is allowed is accepted even
 * when the browser reports a different, non-allowed MIME type (e.g. a `.pdf`
 * reported as `text/plain`). This is a UX convenience to reject the obviously
 * wrong kind of file (`.exe`, `.txt`) without ever rejecting a real file over a
 * missing/garbled MIME type. Content is validated authoritatively server-side,
 * so the client check intentionally errs toward accepting.
 */
export function isAllowedFileType(
  file: { type?: string; name?: string } | null | undefined,
): boolean {
  if (!file) {
    return false;
  }
  if (file.type && allowed_file_types.includes(file.type)) {
    return true;
  }
  return allowed_file_extensions.includes(getFileExtension(file.name));
}
